from django.db import migrations, models


def recopier_liens(apps, schema_editor):
    """Conserve les liens YouTube / TikTok déjà saisis (session et médias vidéo)."""
    from core.video import analyser
    Session = apps.get_model('formations', 'FormationSessionPassee')
    Media = apps.get_model('formations', 'FormationSessionMedia')
    for session in Session.objects.all():
        lien = session.video_apercu_url if analyser(session.video_apercu_url) else ''
        if not lien:
            media = next((m for m in Media.objects.filter(session=session, actif=True).order_by('ordre', 'id')
                          if analyser(m.video_url)), None)
            lien = media.video_url if media else ''
        if lien:
            session.lien_video = lien
            session.save(update_fields=['lien_video'])


